package com.paitrick.blog.auth.controller; import com.paitrick.blog.auth.dto.LoginRequest; import com.paitrick.blog.auth.service.AuthService; import com.paitrick.blog.common.response.ApiResponse; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.Map;
@RestController @RequestMapping("/api/auth") public class AuthController{private final AuthService s;public AuthController(AuthService s){this.s=s;}@PostMapping("/login") ApiResponse<Map<String,String>> login(@Valid @RequestBody LoginRequest r){return ApiResponse.ok(Map.of("token",s.login(r)));}}
